9	const (
10		periodicAnalyzePath = "/v1/schedules/periodic/analyze"
11		maxPeriodicValue    = 1_000_000_000_000
12		maxInt64            = 1<<63 - 1
13		// rtaPrecision is the working precision (bits) for the high-precision
14		// utilization sums; rtaGrayZone is the band around 1 resolved exactly.
15		// 256 bits keeps the jump error below C*n*2^-256/d^2 << 1 even at the
16		// edge of the gray zone, without the cost of wider arithmetic.
17		rtaPrecision = 256
18		rtaGrayZone  = "1e-30"
19	)
20	
21	type periodicTaskIn struct {
