52	func handlePeriodicAnalyze(w http.ResponseWriter, r *http.Request) {
53		if r.Method != http.MethodPost {
54			w.Header().Set("Allow", http.MethodPost)
55			writeAnalyzeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
56			return
57		}
58		var req periodicRequest
59		if !decodeStrictJSON(w, r, &req) {
60			return
61		}
62		tasks, ok := validatePeriodicRequest(&req)
63		if !ok {
64			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
65			return
66		}
67		w.Header().Set("Content-Type", "application/json; charset=utf-8")
68		w.WriteHeader(http.StatusOK)
69		_ = json.NewEncoder(w).Encode(analyzePeriodic(tasks))
70	}
71	
72	func validatePeriodicRequest(req *periodicRequest) ([]periodicTask, bool) {
73		if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
74			return nil, false
75		}
76		tasks := make([]periodicTask, 0, len(*req.Tasks))
77		ids := make(map[string]struct{}, len(*req.Tasks))
78		priorities := make(map[int64]struct{}, len(*req.Tasks))
79		for i := range *req.Tasks {
80			in := (*req.Tasks)[i]
81			if !validTaskID(in.ID) {
82				return nil, false
83			}
84			if _, dup := ids[in.ID]; dup {
85				return nil, false
86			}
87			ids[in.ID] = struct{}{}
88			if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
89				return nil, false
90			}
91			if _, dup := priorities[*in.Priority]; dup {
92				return nil, false
93			}
94			priorities[*in.Priority] = struct{}{}
95			if in.Execution == nil || *in.Execution <= 0 || *in.Execution > maxPeriodicValue {
96				return nil, false
97			}
98			if in.Period == nil || *in.Period <= 0 || *in.Period > maxPeriodicValue {
99				return nil, false
100			}
101			if in.Deadline == nil || *in.Deadline <= 0 || *in.Deadline > maxPeriodicValue ||
102				*in.Deadline > *in.Period {
103				return nil, false
104			}
105			tasks = append(tasks, periodicTask{
106				id:        in.ID,
107				priority:  *in.Priority,
108				execution: *in.Execution,
109				period:    *in.Period,
110				deadline:  *in.Deadline,
111			})
112		}
113		return tasks, true
114	}
115	
116	// analyzePeriodic computes worst-case response times under synchronous
117	// release, fixed priorities, preemptive scheduling, no blocking and no
118	// release jitter (constrained deadlines: deadline <= period).
119	func analyzePeriodic(tasks []periodicTask) periodicResponse {
120		n := len(tasks)
121		// hp[i] lists the strictly higher-priority tasks of task i in input order.
122		hp := make([][]periodicTask, n)
123		for i, t := range tasks {
124			for j := range tasks {
125				if tasks[j].priority < t.priority {
126					hp[i] = append(hp[i], tasks[j])
127				}
128			}
129		}
130	
131		resp := periodicResponse{
132			Schedulable: true,
133			Results:     make([]periodicTaskResult, n),
134		}
135		for i, t := range tasks {
136			rt := worstResponseTime(t, hp[i])
137			result := periodicTaskResult{ID: t.id, ResponseTime: rt}
138			if rt != nil && *rt <= t.deadline {
139				result.DeadlineStatus = "met"
140			} else {
141				result.DeadlineStatus = "missed"
142				resp.Schedulable = false
143			}
144			resp.Results[i] = result
145		}
146		return resp
147	}
148	
149	// interference sums ceil(w/period)*execution over every higher-priority
150	// task. A result of false means the sum exceeds int64.
151	func interference(hp []periodicTask, w int64) (int64, bool) {
152		var sum int64
153		for _, t := range hp {
154			jobs := (w + t.period - 1) / t.period
155			term, ok := saturatingMul(jobs, t.execution)
156			if !ok {
157				return 0, false
158			}
159			sum, ok = saturatingAdd(sum, term)
160			if !ok {
161				return 0, false
162			}
163		}
164		return sum, true
165	}
166	
167	// worstResponseTime returns the least fixed point of
168	//
169	//	w = C + sum_j ceil(w/T_j) * C_j   (j ranging over hp)
170	//
171	// or nil if it does not settle at or before the deadline.
172	//
173	// Semantics:
174	//
175	//   - If the higher-priority utilization U = sum C_j/T_j is at least 1 there
176	//     is no finite fixed point (those tasks alone saturate the processor), so
177	//     the task misses.
178	//   - Otherwise the iteration from w0 = C is a strictly increasing integer
179	//     chain bounded by the least fixed point R; it reaches R or crosses the
180	//     deadline. Starting above R would be wrong: g can admit further, larger
181	//     fixed points even with U < 1, so every accelerated start must be a
182	//     proven lower bound of R.
183	//
184	// Acceleration: since ceil(x/T_j)*C_j >= (x/T_j)*C_j for every x >= 0,
185	// g(x) >= C + U*x, hence R >= C/(1-U) =: j0. Beginning the iteration at j0
186	// skips the well-known pseudo-polynomial blow-up in which tiny per-round
187	// increments walk all the way to a very distant fixed point. The common
188	// path evaluates j0 with high-precision (256-bit) floating point, avoiding
189	// the denominator LCM blow-up an exact rational sum would suffer;
190	// with |1-U| above a 1e-30 gray zone its absolute error is provably below 1,
191	// so floor(j0)-1 is strictly below the exact j0. In the gray zone (which
192	// contains every exact equality such as 1/3+1/3+1/3 == 1) and for obvious
193	// saturation, exact rational arithmetic decides. A start above the deadline
194	// proves a miss because R >= j0 >= start. The residual iteration after the
195	// jump remains, in the worst case, pseudo-polynomial.
196	func worstResponseTime(t periodicTask, hp []periodicTask) *int64 {
197		if t.execution > t.deadline {
198			return nil
199		}
200	
201		start, miss := initialBound(t, hp)
202		if miss {
203			return nil
204		}
205	
206		w := start
207		for {
208			f, ok := interference(hp, w)
209			if !ok {
210				return nil
211			}
212			next, ok := saturatingAdd(t.execution, f)
213			if !ok || next > t.deadline {
214				return nil
215			}
216			if next == w {
217				rt := w
218				return &rt
219			}
220			w = next
221		}
222	}
223	
224	// initialBound returns the iteration start and whether the bound proves the
225	// deadline cannot be met.
226	func initialBound(t periodicTask, hp []periodicTask) (start int64, miss bool) {
227		if len(hp) == 0 {
228			return t.execution, false
229		}
230	
231		// High-precision utilization: error per quotient is < 2^-256, so the
232		// accumulated absolute error is below len(hp)*2^-256.
233		u := new(big.Float).SetPrec(rtaPrecision)
234		for _, h := range hp {
235			q := new(big.Float).SetPrec(rtaPrecision).Quo(
236				new(big.Float).SetPrec(rtaPrecision).SetInt64(h.execution),
237				new(big.Float).SetPrec(rtaPrecision).SetInt64(h.period))
238			u.Add(u, q)
239		}
240		one := new(big.Float).SetPrec(rtaPrecision).SetInt64(1)
241		d := new(big.Float).SetPrec(rtaPrecision).Sub(one, u) // d = 1 - U
242		gray, _ := new(big.Float).SetPrec(rtaPrecision).SetString(rtaGrayZone)
243	
244		if d.Cmp(gray) <= 0 {
245			// Gray zone (d ~ 0) or U > 1: settle utilization exactly.
246			ru := new(big.Rat)
247			for _, h := range hp {
248				ru.Add(ru, new(big.Rat).SetFrac(big.NewInt(h.execution), big.NewInt(h.period)))
249			}
250			if ru.Cmp(big.NewRat(1, 1)) >= 0 {
251				return 0, true
252			}
253			rd := new(big.Rat).Sub(big.NewRat(1, 1), ru)
254			j := new(big.Int).Quo(
255				new(big.Int).Mul(big.NewInt(t.execution), rd.Denom()), rd.Num())
256			if !j.IsInt64() || j.Int64() > t.deadline {
257				return 0, true
258			}
259			if jv := j.Int64(); jv > t.execution {
260				return jv, false
261			}
262			return t.execution, false
263		}
264	
265		// d > gray > 0, so U is certainly below 1. j0 = C/d; the bound
266		// C*n*2^-256/d^2 is below 1 throughout this region, hence floor(j0)-1 is
267		// strictly smaller than the exact j0 for all representable inputs.
268		j0 := new(big.Float).SetPrec(rtaPrecision).Quo(
269			new(big.Float).SetPrec(rtaPrecision).SetInt64(t.execution), d)
270		j, _ := j0.Int(nil) // truncation towards zero; j0 is positive
271		j.Sub(j, big.NewInt(1))
272		if !j.IsInt64() || j.Int64() > t.deadline {
273			return 0, true
274		}
275		if jv := j.Int64(); jv > t.execution {
276			return jv, false
277		}
278		return t.execution, false
279	}
280	
281	func saturatingAdd(a, b int64) (int64, bool) {
282		if b > maxInt64-a {
283			return 0, false
284		}
285		return a + b, true
286	}
287	
288	func saturatingMul(a, b int64) (int64, bool) {
289		if a == 0 || b == 0 {
290			return 0, true
291		}
292		if a > maxInt64/b {
293			return 0, false
294		}
295		return a * b, true
296	}
