259	// simulation over [0, horizon).
260	func simulateSchedule(tasks []scheduledTask, horizon int64) analyzeResponse {
261		n := len(tasks)
262		remaining := make([]int64, n)
263		for i, t := range tasks {
264			remaining[i] = t.execution
265		}
266		released := make([]bool, n)
267		executed := make([]int64, n)
268		completion := make([]*int64, n)
269	
270		// Indices sorted by (release, input order) for release bookkeeping and
271		// same-priority tie breaking.
272		order := make([]int, n)
273		for i := range order {
274			order[i] = i
275		}
276		sort.Slice(order, func(a, b int) bool {
277			ia, ib := order[a], order[b]
278			if tasks[ia].release != tasks[ib].release {
279				return tasks[ia].release < tasks[ib].release
280			}
281			return ia < ib
282		})
283		nextRelease := 0
284		releaseUpTo := func(now int64) {
285			for nextRelease < n && tasks[order[nextRelease]].release <= now {
286				released[order[nextRelease]] = true
287				nextRelease++
288			}
289		}
290	
291		// Best runnable task: smallest priority, then earliest release, then
292		// earliest input index.
293		bestRunnable := func() int {
294			best := -1
295			for i := 0; i < n; i++ {
296				if !released[i] || remaining[i] <= 0 {
297					continue
298				}
299				if best == -1 {
300					best = i
301					continue
302				}
303				a, b := tasks[i], tasks[best]
304				if a.priority < b.priority ||
305					(a.priority == b.priority && a.release < b.release) ||
306					(a.priority == b.priority && a.release == b.release && i < best) {
307					best = i
308				}
309			}
310			return best
311		}
312	
313		var segments []executionSegment
314		current := -1
315		var now int64
316		for now < horizon {
317			releaseUpTo(now)
318			if current >= 0 && remaining[current] == 0 {
319				current = -1
320			}
321			best := bestRunnable()
322			switch {
323			case current == -1:
324				current = best
325			case best != -1 && tasks[best].priority < tasks[current].priority:
326				// Strictly higher priority preempts; equal priority never does.
327				current = best
328			}
329	
330			if current == -1 {
331				// Idle: jump to the next release (or the horizon).
332				if nextRelease >= n {
333					now = horizon
334					break
335				}
336				now = tasks[order[nextRelease]].release
337				continue
338			}
339	
340			// Run until completion, the horizon, or the next strictly-higher-priority
341			// release, whichever comes first.
342			runEnd := horizon
343			if remaining[current] < horizon-now {
344				runEnd = now + remaining[current]
345			}
346			for k := nextRelease; k < n; k++ {
347				j := order[k]
348				if tasks[j].priority < tasks[current].priority &&
349					tasks[j].release > now && tasks[j].release < runEnd {
350					runEnd = tasks[j].release
351				}
352			}
353	
354			segments = append(segments, executionSegment{index: current, start: now, end: runEnd})
355			delta := runEnd - now
356			executed[current] += delta
357			remaining[current] -= delta
358			now = runEnd
359			if remaining[current] == 0 {
360				done := now
361				completion[current] = &done
362				current = -1
363			}
364		}
365	
366		timeline := make([]timelineInterval, 0, len(segments))
367		for _, seg := range segments {
368			last := len(timeline) - 1
369			if last >= 0 && timeline[last].TaskID == tasks[seg.index].id && timeline[last].End == seg.start {
370				timeline[last].End = seg.end
371				continue
372			}
373			timeline = append(timeline, timelineInterval{
374				TaskID: tasks[seg.index].id,
375				Start:  seg.start,
376				End:    seg.end,
377			})
378		}
379	
380		results := make([]taskResult, n)
381		for i, t := range tasks {
382			var status string
383			switch c := completion[i]; {
384			case c != nil:
