func TestPeriodicSimulateNoPartialResultsOnError(t *testing.T) {
	rec := postPeriodicSimulate(t, `{"horizon":10,"tasks":[{"id":"a"`, "application/json")
	assertErrorCode(t, rec, http.StatusBadRequest, "invalid_json")
